{
  "name": "Luminos 电动精密位移台轴模块",
  "name_en": "Luminos motorized precision stage axis",
  "manufacturer": "",
  "description": "Luminos 电动精密位移台轴模块是一类用于精密定位的机电运动单元，可作为线性轴（X、Y、Z）或旋转轴（滚转、偏航、俯仰）组成多自由度位移台。它常用于实验室中对样品、光学元件、探针或夹具进行高精度移动、对准、调焦和扫描。",
  "description_en": "The Luminos motorized precision stage axis is an electromechanical positioning module used for fine motion control. It can serve as a linear axis (X, Y, Z) or a rotary axis (roll, yaw, pitch) within a multi-axis stage system. It is commonly used in laboratories for precise movement, alignment, focusing, and scanning of samples, optical components, probes, or fixtures.",
  "tag_hints": [
    "motorized positioning stage",
    "optical alignment",
    "linear and rotary motion",
    "precision motion control",
    "microstepping",
    "homing",
    "multi-axis stage"
  ],
  "actions": [
    {
      "action_name": "auto-move_rel",
      "description": "使该轴执行相对位移。",
      "description_en": "Move this axis by a relative displacement."
    },
    {
      "action_name": "auto-move_abs",
      "description": "使该轴移动到绝对位置。",
      "description_en": "Move this axis to an absolute position."
    },
    {
      "action_name": "auto-turn_leds_off",
      "description": "关闭设备指示灯。",
      "description_en": "Turn off the device LEDs."
    },
    {
      "action_name": "auto-turn_leds_on",
      "description": "打开设备指示灯。",
      "description_en": "Turn on the device LEDs."
    },
    {
      "action_name": "auto-enable_motor_knob",
      "description": "启用电机旋钮手动控制。",
      "description_en": "Enable manual control using the motor knob."
    },
    {
      "action_name": "auto-disable_motor_knob",
      "description": "禁用电机旋钮手动控制。",
      "description_en": "Disable manual control using the motor knob."
    },
    {
      "action_name": "auto-enable_manual_move_reply",
      "description": "启用手动移动反馈。",
      "description_en": "Enable manual move feedback."
    },
    {
      "action_name": "auto-disable_manual_move_reply",
      "description": "禁用手动移动反馈。",
      "description_en": "Disable manual move feedback."
    },
    {
      "action_name": "auto-enable_circular_phase_microstepping",
      "description": "启用圆相位微步模式。",
      "description_en": "Enable circular-phase microstepping."
    },
    {
      "action_name": "auto-disable_circular_phase_microstepping",
      "description": "禁用圆相位微步模式。",
      "description_en": "Disable circular-phase microstepping."
    },
    {
      "action_name": "auto-enable_anti_backlash_routine",
      "description": "启用消隙程序。",
      "description_en": "Enable the anti-backlash routine."
    },
    {
      "action_name": "auto-disable_anti_backlash_routine",
      "description": "禁用消隙程序。",
      "description_en": "Disable the anti-backlash routine."
    },
    {
      "action_name": "auto-enable_anti_sticktion_routine",
      "description": "启用防静摩擦程序。",
      "description_en": "Enable the anti-stiction routine."
    },
    {
      "action_name": "auto-disable_anti_sticktion_routine",
      "description": "禁用防静摩擦程序。",
      "description_en": "Disable the anti-stiction routine."
    },
    {
      "action_name": "auto-enable_move_tracking",
      "description": "启用运动跟踪。",
      "description_en": "Enable move tracking."
    },
    {
      "action_name": "auto-disable_move_tracking",
      "description": "禁用运动跟踪。",
      "description_en": "Disable move tracking."
    },
    {
      "action_name": "auto-set_speed",
      "description": "设置轴速度。",
      "description_en": "Set the axis speed."
    },
    {
      "action_name": "auto-set_acceleration",
      "description": "设置轴加速度。",
      "description_en": "Set the axis acceleration."
    },
    {
      "action_name": "auto-set_microstep_resolution",
      "description": "设置微步分辨率。",
      "description_en": "Set the microstep resolution."
    },
    {
      "action_name": "auto-home",
      "description": "使该轴回零。",
      "description_en": "Home this axis."
    },
    {
      "action_name": "auto-get_device_mode_bit_status",
      "description": "获取设备模式位状态。",
      "description_en": "Get the status of a device mode bit."
    },
    {
      "action_name": "auto-get_speed",
      "description": "获取轴速度。",
      "description_en": "Get the axis speed."
    },
    {
      "action_name": "auto-get_acceleration",
      "description": "获取轴加速度。",
      "description_en": "Get the axis acceleration."
    },
    {
      "action_name": "auto-get_microstep_resolution",
      "description": "获取微步分辨率。",
      "description_en": "Get the microstep resolution."
    },
    {
      "action_name": "auto-set_default_settings",
      "description": "恢复或应用默认设置。",
      "description_en": "Restore or apply the default settings."
    },
    {
      "action_name": "auto-set_manual_mode",
      "description": "将设备设为手动模式。",
      "description_en": "Set the device to manual mode."
    },
    {
      "action_name": "auto-set_computer_mode",
      "description": "将设备设为计算机控制模式。",
      "description_en": "Set the device to computer-control mode."
    },
    {
      "action_name": "auto-flash_leds",
      "description": "闪烁设备指示灯。",
      "description_en": "Flash the device LEDs."
    },
    {
      "action_name": "auto-nm_per_step",
      "description": "获取每步对应的纳米位移。",
      "description_en": "Get the nanometers of travel per step."
    },
    {
      "action_name": "auto-arc_second_per_step",
      "description": "获取每步对应的角秒位移。",
      "description_en": "Get the angular travel in arcseconds per step."
    }
  ]
}

